import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const proofPath = join(__dirname, '..', 'tenant-proof.json');

test('tenant-proof.json exists and has required fields', () => {
  const proof = JSON.parse(readFileSync(proofPath, 'utf8'));
  assert.ok(proof.factoryName, 'factoryName must be present');
  assert.ok(proof.datasetId, 'datasetId must be present');
  assert.ok(proof.marker, 'marker must be present');
});

test('tenant-proof.json factoryName matches the real exported factory from monitor-client', () => {
  const proof = JSON.parse(readFileSync(proofPath, 'utf8'));
  // The factory exported from src/monitor-client.ts
  assert.equal(proof.factoryName, 'createMonitorClient');
});

test('tenant-proof.json datasetId is dataset-a', () => {
  const proof = JSON.parse(readFileSync(proofPath, 'utf8'));
  assert.equal(proof.datasetId, 'dataset-a');
});

test('tenant-proof.json marker is a non-empty string from the tenant dataset', () => {
  const proof = JSON.parse(readFileSync(proofPath, 'utf8'));
  assert.equal(typeof proof.marker, 'string');
  assert.ok(proof.marker.length > 0, 'marker must not be empty');
  assert.equal(proof.marker, 'file-a-2b66d02d038c036ea5b94340');
});

